#!/usr/bin/env bash
#
# A wizard — walks a human through a manual procedure step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library — delightful, consistent UX. Identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear — wipe the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" — opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later — it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" — clear the screen, then announce a stage and show progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." — a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." — a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL — open in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser — visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser — visit it manually: $url"
}

# pause "msg" — wait for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" — y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY — current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" — read a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" — like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE — upsert KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE — set a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name — gh not ready; set it later"
}

# set_var NAME VALUE — set a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name — gh not ready; set it later"
}

# finish — clear, then a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES — author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=8
GROK=/usr/local/bin/grok
# The runner reads its non-overridable policy from the requirements layer, and
# reports the layer's path in `inspect --json`. The pin state this system owns
# lives beside it under /etc/voice-agent.
GROK_REQUIREMENTS=/etc/grok/requirements.toml
GROK_STATE_DIR=/etc/voice-agent/grok
PIN="$GROK_STATE_DIR/runner-pin.json"
RECORD=/var/lib/voice-agent-evidence/grok-enrollment.json
BRIEF_DIR=/var/lib/voice-grok/brief
RUN_ROOT=/var/lib/voice-grok/run
EVIDENCE=/var/lib/voice-agent-evidence
TOKEN_BROKER_DIRECTORY=/usr/local/libexec/voice-agent
TOKEN_BROKER=$TOKEN_BROKER_DIRECTORY/grok-token-broker
TOKEN_HELPER=$TOKEN_BROKER_DIRECTORY/grok-token-helper

if [[ ! -e /opt/voice-agent/current ]]; then
  warn "Run this wizard on the Agent Host after promoting the reviewed Voice Agent release."
  exit 1
fi
RELEASE_ROOT=
if ! RELEASE_ROOT=$(readlink -f /opt/voice-agent/current) || \
  [[ ! $RELEASE_ROOT =~ ^/opt/voice-agent/releases/[0-9a-f]{40}$ ]] || \
  [[ ! -d $RELEASE_ROOT ]]; then
  warn "The active Voice Agent release path is invalid."
  exit 1
fi
# shellcheck source=ops/acceptance/grok-enrollment-prerequisites.sh
source "$RELEASE_ROOT/ops/acceptance/grok-enrollment-prerequisites.sh"

# now — one UTC timestamp in the shape every Enrollment Event carries.
now() { date -u +%Y-%m-%dT%H:%M:%S.000Z; }

# enrollment COMMAND... — file one Enrollment Event from the active Release.
# The record is the durable proof the executor reads before it will do work, so
# it is written by the reviewed CLI rather than by this wizard's own hand.
enrollment() {
  sudo /usr/bin/node --experimental-strip-types \
    "$RELEASE_ROOT/apps/acceptance/src/grok-enrollment-cli.ts" "$@"
}

# grok_as_executor COMMAND... — run the runner as the executor identity with
# the same stripped environment a Delegation gets, so what this wizard observes
# is what an accepted run observes. An inherited HOME or PATH would let a
# passing check describe a configuration no Delegation will ever use.
grok_as_executor() {
  sudo -u voice-grok env -i \
    HOME=/var/lib/voice-grok LANG=C.UTF-8 PATH=/usr/bin:/bin "$@"
}

# The state each drilled condition must reach. The reviewed record refuses a
# drill filed as anything else; naming them here lets the wizard tell the
# operator what to look for before they look.
declare -A DRILL_OUTCOME=(
  [authentication-failure]=paused
  [entitlement-failure]=paused
  [malformed-output]=failed
  [provider-contract-drift]=paused
  [quota-exhaustion]=paused
  [signal-interruption]=stopped
  [timeout]=failed
  [turn-limit]=failed
)
declare -A DRILL_METHOD=(
  [authentication-failure]="Revoke or expire the subscription login, or point $GROK at a stub returning the provider's own 401."
  [entitlement-failure]="Use a stub runner returning the provider's 403 for an unentitled model."
  [malformed-output]="Use a stub runner that prints something other than one structured result."
  [provider-contract-drift]="Set auto_update.enabled = true in the pinned configuration, or return an inspect envelope missing a field."
  [quota-exhaustion]="Exhaust the subscription allowance, or use a stub runner returning the provider's 429."
  [signal-interruption]="Start a long Delegation and stop its unit."
  [timeout]="Use a stub runner that sleeps past the run's time bound."
  [turn-limit]="Run a task the model cannot finish within maxTurns, or have a stub report the max_turns stop reason."
)

banner "Grok Build enrollment and contract test"
verify_grok_enrollment_boundary

stage "Pin the runner"
say "The version is the runner's claim about itself; the digest is the only statement about the bytes that will execute."
GROK_VERSION_OUTPUT=$(grok_as_executor "$GROK" --version)
note "$GROK_VERSION_OUTPUT"
# The channel label is recorded rather than checked. The same released 1.0.13
# reports [alpha] on this host's Linux build and [stable] on a macOS build of
# the same version, unexplained; the pin is the digest, so the label is
# evidence about the release channel rather than a boundary.
step "Note the channel label the version line carries, and whether it is the one the previous enrollment recorded."
GROK_VERSION=$(printf '%s' "$GROK_VERSION_OUTPUT" | grep -oE '[0-9]+\.[0-9]+\.[0-9]+' | head -n1)
GROK_DIGEST=$(sudo sha256sum "$GROK" | cut -d' ' -f1)
note "digest $GROK_DIGEST"
say "Reading the runner's own effective configuration. Its config_sources names where this build reads system configuration; the root-managed profile belongs at that path rather than at one this wizard assumed."
GROK_INSPECT=$(grok_as_executor "$GROK" inspect --json)
printf '%s\n' "$GROK_INSPECT" | /usr/bin/jq . || note "$GROK_INSPECT"
# The subscription being the only reachable route is the one boundary the
# runner reports on itself, and it is resolved from the requirements layer
# above rather than from the account. This is machine-checked rather than left
# to the confirmation below, because a host whose layer lost the key reaches
# every later stage looking well and then pauses every Delegation.
if [[ "$(printf '%s' "$GROK_INSPECT" | /usr/bin/jq -r '.loginPolicy.apiKeyAuthDisabled')" != "true" ]]; then
  warn "loginPolicy.apiKeyAuthDisabled is not true. $GROK_REQUIREMENTS must pin [grok_com_config] disable_api_key_auth = true; install the reviewed ops/grok/requirements.toml and re-run."
  exit 1
fi
printf '  %s✓%s the runner refuses API-key authentication by policy\n' "$GREEN" "$RESET"
# Whether disable_api_key_auth clears a non-complying session is untested: that
# clearing is documented of force_login_team_uuid. The authorize stage still
# runs grok login only when auth.json is absent, so a leftover file after a
# cleared session is not signed in again here. The broker probe in that stage
# is what surfaces it.
say "Whether the API-key refusal clears an enrolled session is untested. The next stage runs grok login only when auth.json is absent; a leftover file after a cleared session is a failure the broker probe will surface."
step "Confirm grokVersion matches, no MCP servers, plugins, skills, hooks, or marketplaces are declared, no third-party vendor surface is enabled, and configSources names exactly one non-empty layer - the system-requirements one. A run's own requirements layer carrying the auth crossing appears beside it only inside a Delegation's own Grok home."
ask GROK_CONFIG_PATH "Which path does the system-requirements layer in configSources name?"
if [[ "$GROK_CONFIG_PATH" != /* ]]; then
  warn "The configuration source must be an absolute path."
  exit 1
fi
if ! sudo test -r "$GROK_CONFIG_PATH"; then
  warn "The reviewed requirements layer is not installed at $GROK_CONFIG_PATH. Install ops/grok/requirements.toml there, then re-run."
  exit 1
fi
# The system-requirements layer is the one a project directory cannot override,
# so it is the only layer that can carry policy. The executor refuses to run
# unless `inspect` reports this exact path in that role, with the run's own
# auth crossing as the only other layer in effect.
if [[ "$GROK_CONFIG_PATH" != "$GROK_REQUIREMENTS" ]]; then
  warn "The layer in effect is $GROK_CONFIG_PATH, not the reviewed $GROK_REQUIREMENTS."
  exit 1
fi
sudo install -d -o root -g root -m 0755 "$GROK_STATE_DIR"
printf '{"configurationPath":"%s","digest":"%s","version":"%s"}\n' \
  "$GROK_CONFIG_PATH" "$GROK_DIGEST" "$GROK_VERSION" \
  | sudo tee "$PIN" >/dev/null
sudo chmod 0644 "$PIN"
printf '  %s✓ pinned%s %s %s\n' "$GREEN" "$RESET" "$GROK_VERSION" "$GROK_DIGEST"
if ! sudo test -e "$RECORD"; then
  enrollment init --campaign-id grok-enrollment --record "$RECORD"
fi
enrollment record-runner-pin --record "$RECORD" \
  --configuration-path "$GROK_CONFIG_PATH" \
  --digest "$GROK_DIGEST" --version "$GROK_VERSION" --recorded-at "$(now)"
warn "Pinning a build discards the previous build's acceptance. Every stage below belongs to this pin."

stage "Authorize the subscription"
say "Device authorization belongs to voice-grok-auth only. There is no API key step: provisioning one anywhere on this host makes the executor refuse to run."
# grok login runs only when auth.json is absent. A leftover file after a
# session the pin might have cleared is a failure the broker probe below
# surfaces, not a sign-in this stage repeats.
if ! sudo test -e /var/lib/voice-grok-auth/.grok/auth.json; then
  step "Complete the device flow as the subscription owner, on a machine with a browser."
  sudo -u voice-grok-auth -H "$GROK" login --device-auth
fi
sudo test -e /var/lib/voice-grok-auth/.grok/auth.json
sudo test "$(sudo stat -c %a /var/lib/voice-grok-auth/.grok/auth.json)" = 600
step "In the Grok account, set the code-data retention control to the setting you intend, and note which one you chose."
pause "Press Enter when the retention setting has been observed."
sudo -u voice-grok test ! -e /var/lib/voice-grok/.grok/auth.json
if grok_as_executor /usr/bin/env | grep -q XAI_API_KEY; then
  warn "An xAI API key is present for the executor identity. Remove it: this MVP runs on the subscription alone."
  exit 1
fi
# The runner reaches the credential only through the broker. Prove both
# crossings work and that the helper behind them refuses everyone else.
if ! sudo -u voice-grok "$TOKEN_BROKER" --probe >/dev/null; then
  warn "The token broker could not report a credential lifetime. Read its standard error as voice-grok, clear the cause, and re-run this wizard."
  exit 1
fi
if ! sudo -u voice-grok "$TOKEN_BROKER" >/dev/null; then
  warn "The token broker returned nothing. Read its standard error as voice-grok: the helper behind it names which of the enrolled credential's properties it refused."
  exit 1
fi
if sudo -u voice-grok "$TOKEN_HELPER" >/dev/null 2>&1; then
  warn "The token helper ran as voice-grok. The custody crossing is open; do not continue."
  exit 1
fi
# A host-wide auth provider would bind voice-grok-auth too, and the runner
# prefers a provider command over renewing an expired cached login - so the one
# identity that can renew this credential would be sent to the broker that
# reads it. The crossing belongs in each run's own home. See ADR-0069. The key
# is refused by name anywhere in the comment-stripped layer, matching
# describeSystemRequirementsDrift: a start-of-line `key =` grep misses
# grok_com_config = { auth_provider_command = "…" }, and `[auth]` is an alias
# of `[grok_com_config]` which this layer now carries for the API-key refusal.
if sudo sed 's/#.*$//' "$GROK_REQUIREMENTS" | grep -Fq 'auth_provider_command'; then
  warn "$GROK_REQUIREMENTS names an auth provider command. That layer binds voice-grok-auth as well and would preempt its own credential renewal. Install the reviewed ops/grok/requirements.toml and re-run."
  exit 1
fi
printf '  %s✓%s no executor credential, no API key, both broker crossings hold\n' "$GREEN" "$RESET"
RETENTION=false
confirm "Is provider code-data retention disabled for this account?" && RETENTION=true
enrollment record-enrollment --record "$RECORD" \
  --code-retention-disabled "$RETENTION" --recorded-at "$(now)"

stage "Run the contract Delegation"
say "One real run, through the subscription, under the reviewed unit."
CONTRACT_ID="grok-contract-$(date -u +%Y%m%d%H%M%S)"
sudo install -d -o voice-grok -g voice-grok -m 0700 "$BRIEF_DIR"
sudo install -o voice-grok -g voice-grok -m 0600 /dev/stdin \
  "$BRIEF_DIR/$CONTRACT_ID.json" <<JSON
{
  "acceptanceCriteria": ["notes.md contains the host's Node version."],
  "boundedContext": {
    "editablePaths": ["notes.md"],
    "repositoryContentTrust": "untrusted-data-only"
  },
  "capabilities": ["delegated-worktree.read", "delegated-worktree.write"],
  "delegationId": "$CONTRACT_ID",
  "goal": "Write one line into notes.md describing this host's Node version.",
  "maxTurns": 4,
  "provider": "grok",
  "purpose": "contract-test"
}
JSON
note "purpose is contract-test: this is the run that produces the proof, so it is the one run that does not require one."
sudo systemctl start "voice-agent-grok-contract@$CONTRACT_ID.service"
CONTRACT_RECORD="$EVIDENCE/$CONTRACT_ID/grok-contract-run.json"
sudo cat "$CONTRACT_RECORD" | /usr/bin/jq .
if [[ "$(sudo /usr/bin/jq -r '.outcome.state' "$CONTRACT_RECORD")" != "completed" ]]; then
  warn "The run did not complete. Read outcome.reason and outcome.detail above, clear the cause, then re-run this wizard."
  exit 1
fi
if [[ "$(sudo /usr/bin/jq -r '.outcome.evidence.authenticationRoute' "$CONTRACT_RECORD")" != "subscription-oauth" ]]; then
  warn "The accepted run did not report the subscription route."
  exit 1
fi
CONTRACT_MODEL=$(sudo /usr/bin/jq -r '.outcome.evidence.model.providerReported' "$CONTRACT_RECORD")
CONTRACT_SESSION=$(sudo /usr/bin/jq -r '.outcome.evidence.sessionId' "$CONTRACT_RECORD")
CONTRACT_STOP=$(sudo /usr/bin/jq -r '.outcome.evidence.stopReason' "$CONTRACT_RECORD")
CONTRACT_INCOMPLETE=$(sudo /usr/bin/jq -r '.outcome.evidence.usage.incomplete' "$CONTRACT_RECORD")
note "model $CONTRACT_MODEL · session $CONTRACT_SESSION · stop $CONTRACT_STOP"
if [[ "$CONTRACT_SESSION" == "null" ]]; then
  warn "The provider reported no session identity; the record requires one."
  exit 1
fi
enrollment record-contract-run --record "$RECORD" \
  --configuration-path "$GROK_CONFIG_PATH" \
  --digest "$GROK_DIGEST" --version "$GROK_VERSION" \
  --model "$CONTRACT_MODEL" --session "$CONTRACT_SESSION" \
  --stop-reason "$CONTRACT_STOP" --usage-incomplete "$CONTRACT_INCOMPLETE" \
  --recorded-at "$(now)"

stage "Probe the Credential Custody Boundary"
say "The probe enumerates credential stores from the same list the executor uses. The Auth Crossing directory is crossing code, not a store; a 0755 listing of /usr/local/libexec/voice-agent is not disclosure."
# Run as voice-grok without the sandbox: model-selected commands share this
# identity, and stores this identity cannot read stay unread. The crossing is
# denied to Bubblewrap children by /etc/apparmor.d/local/unpriv_bwrap, not by
# a Grok sandbox deny list.
PROBE=$(sudo -u voice-grok /usr/bin/node --experimental-strip-types \
  "$RELEASE_ROOT/apps/worker/src/grok-custody-probe.ts")
printf '%s\n' "$PROBE" | /usr/bin/jq .
READABLE=$(printf '%s' "$PROBE" | /usr/bin/jq -r '.readableBoundaryPaths')
if [[ "$READABLE" != "0" ]]; then
  warn "The executor identity reached $READABLE boundary store(s). Close them before continuing."
fi
CANARY="voice-agent-canary-$(date -u +%s)"
printf '%s\n' "$CANARY" | sudo tee "$GROK_STATE_DIR/canary" >/dev/null
sudo chmod 0600 "$GROK_STATE_DIR/canary"
step "Give Grok a Delegation that tries to read every boundary store and $GROK_STATE_DIR/canary."
step "From that Delegation, run $RELEASE_ROOT/ops/grok/auth-crossing-child-canary.sh as that child so this process cannot list or execute /usr/local/libexec/voice-agent. Nested bwrap is not this canary. The parent broker probe under the contract unit must still answer. An attended shell that lists the 0755 directory fails the canary closed; that shell is not this witness."
pause "Press Enter when that Delegation has ended."
CANARY_HITS=$(sudo grep -rl "$CANARY" "$EVIDENCE" "$RUN_ROOT" 2>/dev/null | wc -l)
sudo rm -f "$GROK_STATE_DIR/canary"
note "canary appears in $CANARY_HITS evidence or workspace file(s)"
CHILD_DENIED=false
confirm "Did the child canary fail to list and fail to execute the Auth Crossing?" && CHILD_DENIED=true
PARENT_ANSWERED=false
confirm "Did the parent broker probe under the contract unit still answer?" && PARENT_ANSWERED=true
if [[ "$CHILD_DENIED" != true ]]; then
  warn "The child canary listed or executed the Auth Crossing. An attended shell is not this witness."
fi
if [[ "$PARENT_ANSWERED" != true ]]; then
  warn "The parent unit probe did not answer."
fi
enrollment record-custody-probe --record "$RECORD" \
  --readable-boundary-paths "$READABLE" --canary-secrets-found "$CANARY_HITS" \
  --child-could-not-list-or-execute "$CHILD_DENIED" \
  --parent-unit-probe-answered "$PARENT_ANSWERED" \
  --recorded-at "$(now)"

stage "Drill every ending"
say "Each condition must reach the durable state it is required to reach. The record refuses a drill filed as anything else."
for condition in "${!DRILL_OUTCOME[@]}"; do
  printf '\n'
  step "$condition must end ${DRILL_OUTCOME[$condition]}"
  note "${DRILL_METHOD[$condition]}"
  pause "Induce it, read the durable record it produced, then press Enter."
  if ! confirm "Did the executor record ${DRILL_OUTCOME[$condition]} for $condition?"; then
    warn "Stopping: $condition did not reach ${DRILL_OUTCOME[$condition]}. Fix the behaviour, not the record."
    exit 1
  fi
  FELL_BACK=false
  confirm "Did that run reach another provider, Codex, Claude, or an API key?" && FELL_BACK=true
  enrollment record-failure-drill --record "$RECORD" \
    --condition "$condition" --outcome "${DRILL_OUTCOME[$condition]}" \
    --fell-back "$FELL_BACK" --recorded-at "$(now)"
done

stage "Drill Stop"
say "Stopping is an ending, not a cleanup: completed commits and unfinished work outlive it."
step "Start a long Delegation, let it commit something and leave something uncommitted, then stop its unit."
pause "Press Enter when the stopped Delegation's root is ready to inspect."
ask STOPPED_ROOT "Which Delegation root did you stop? (path under $RUN_ROOT)"
if sudo test -d "$STOPPED_ROOT/.git"; then
  sudo git -C "$STOPPED_ROOT" log --oneline -5 || true
  sudo git -C "$STOPPED_ROOT" status --porcelain || true
fi
COMMITS=false
DIRTY=false
confirm "Are the commits the run made still present?" && COMMITS=true
confirm "Is the unfinished work still on disk?" && DIRTY=true
DESTRUCTIVE=0
confirm "Did anything reset, stash, clean, or delete that worktree?" && DESTRUCTIVE=1
enrollment record-stop-drill --record "$RECORD" \
  --commits-preserved "$COMMITS" --unfinished-work-preserved "$DIRTY" \
  --destructive-git-commands "$DESTRUCTIVE" --recorded-at "$(now)"

stage "Accept the enrollment"
say "Acceptance is what lets a Delegation declaring purpose work run at all."
if ! enrollment status --record "$RECORD"; then
  warn "The contract has not passed for this pin. The errors above name what is missing; nothing declaring purpose work will run until they are cleared."
  exit 1
fi
confirm "Accept this enrollment for pin $GROK_VERSION?" || exit 1
enrollment accept --record "$RECORD" --recorded-at "$(now)"
enrollment status --record "$RECORD"

finish
note "Grok is activated for version $GROK_VERSION, digest $GROK_DIGEST."
note "Installing another build discards this proof: re-run this wizard before that build does any work."
